     1→// 🦎 Phase 5: LLVM IR Backend
     2→// src/llvm_ir.zig
     3→
     4→const std = @import("std");
     5→const Air = @import("air.zig").Air;
     6→const AirType = @import("air.zig").Type;
     7→const Ref = @import("air.zig").Ref;
     8→const Instruction = @import("air.zig").Instruction;
     9→
    10→/// Phase 5 Defer 엔트리 (Phase 4와 동일)
    11→pub const DeferEntry = struct {
    12→    expr_ref: Ref,
    13→    defer_index: u32,
    14→};
    15→
    16→/// Phase 5: LLVM IR 백엔드 (텍스트 형식 생성)
    17→pub const LLVMIRGen = struct {
    18→    air: *const Air,
    19→    allocator: std.mem.Allocator,
    20→    output: std.ArrayList(u8),
    21→    temp_counter: u32,                                      // _tN 자동 증가
    22→    label_counter: u32,                                     // 기본 블록 레이블 번호
    23→    ref_to_value: std.AutoHashMap(Ref, []const u8),         // Ref → "%_tN"
    24→    alloca_map: std.AutoHashMap(u32, []const u8),           // name_index → alloca ptr
    25→    current_fn: ?[]const u8,                                // 현재 함수명
    26→    string_cache: std.StringHashMap([]const u8),            // 전역 문자열 상수 dedup
    27→    indent_level: usize,                                    // 들여쓰기 레벨
    28→    // Phase 5.3: Advanced Features
    29→    switch_subject_stack: std.ArrayList([]const u8),        // 중첩 switch 지원
    30→    error_counter: u32,                                     // _err_N 카운터
    31→    try_ref_to_err: std.AutoHashMap(Ref, []const u8),       // try ref → "_err_N"
    32→    deferred_by_scope: std.AutoHashMap(u32, std.ArrayList(DeferEntry)), // scope → defer list
    33→
    34→    pub fn init(allocator: std.mem.Allocator, air: *const Air) !LLVMIRGen {
    35→        return LLVMIRGen{
    36→            .air = air,
    37→            .allocator = allocator,
    38→            .output = std.ArrayList(u8).init(allocator),
    39→            .temp_counter = 0,
    40→            .label_counter = 0,
    41→            .ref_to_value = std.AutoHashMap(Ref, []const u8).init(allocator),
    42→            .alloca_map = std.AutoHashMap(u32, []const u8).init(allocator),
    43→            .current_fn = null,
    44→            .string_cache = std.StringHashMap([]const u8).init(allocator),
    45→            .indent_level = 0,
    46→            .switch_subject_stack = std.ArrayList([]const u8).init(allocator),
    47→            .error_counter = 0,
    48→            .try_ref_to_err = std.AutoHashMap(Ref, []const u8).init(allocator),
    49→            .deferred_by_scope = std.AutoHashMap(u32, std.ArrayList(DeferEntry)).init(allocator),
    50→        };
    51→    }
    52→
    53→    pub fn deinit(self: *LLVMIRGen) void {
    54→        self.output.deinit();
    55→        self.ref_to_value.deinit();
    56→        self.alloca_map.deinit();
    57→        self.string_cache.deinit();
    58→        self.switch_subject_stack.deinit();
    59→        self.try_ref_to_err.deinit();
    60→
    61→        var iter = self.deferred_by_scope.iterator();
    62→        while (iter.next()) |entry| {
    63→            entry.value_ptr.deinit();
    64→        }
    65→        self.deferred_by_scope.deinit();
    66→    }
    67→
    68→    /// LLVM IR 코드 생성 시작
    69→    pub fn generate(self: *LLVMIRGen) ![]const u8 {
    70→        try self.emitPreamble();
    71→        try self.emitDeclarations();
    72→        return self.output.items;
    73→    }
    74→
    75→    /// 모듈 프리앰블 (target, datalayout)
    76→    fn emitPreamble(self: *LLVMIRGen) !void {
    77→        try self.output.appendSlice("; Generated by Zig LLVM IR Backend\n");
    78→        try self.output.appendSlice("target triple = \"x86_64-unknown-linux-gnu\"\n");
    79→        try self.output.appendSlice("target datalayout = \"e-m:e-i64:64-f80:128-n8:16:32:64-S128\"\n\n");
    80→    }
    81→
    82→    /// 모든 선언(함수, 전역 변수 등) 출력
    83→    fn emitDeclarations(self: *LLVMIRGen) !void {
    84→        for (self.air.instructions.items, 0..) |inst, idx| {
    85→            const ref: Ref = @intCast(idx);
    86→            try self.emitInstruction(inst, ref);
    87→        }
    88→    }
    89→
    90→    // ========== 타입 변환 ==========
    91→
    92→    /// AirType → LLVM IR 타입 문자열
    93→    fn typeToLLVM(self: *LLVMIRGen, ty: AirType) ![]const u8 {
    94→        _ = self;
    95→        return switch (ty) {
    96→            .void => "void",
    97→            .i32 => "i32",
    98→            .i64 => "i64",
    99→            .f32 => "float",
   100→            .f64 => "double",
   101→            .bool => "i1",
   102→            .string => "i8*",
   103→            .array => "array", // TODO: 배열 타입 처리
   104→            .slice => "i8*", // 슬라이스는 포인터
   105→            .function => "function", // TODO: 함수 포인터
   106→            .error_type => "i32", // 에러 코드
   107→            .error_union => "i32", // 에러 유니온 (단순화)
   108→            .pattern => "i32", // 패턴 결과
   109→            .unknown => "i32",
   110→        };
   111→    }
   112→
   113→    /// Ref를 LLVM IR 값으로 변환 ("%_tN" 또는 "%{var_name}")
   114→    fn refToValue(self: *LLVMIRGen, ref: Ref) ![]const u8 {
   115→        if (self.ref_to_value.get(ref)) |val| {
   116→            return val;
   117→        }
   118→        return try std.fmt.allocPrint(self.allocator, "%_t{}", .{ref});
   119→    }
   120→
   121→    /// 새 임시 변수 생성 ("%_tN")
   122→    fn genTempVar(self: *LLVMIRGen) ![]const u8 {
   123→        const name = try std.fmt.allocPrint(self.allocator, "%_t{}", .{self.temp_counter});
   124→        self.temp_counter += 1;
   125→        return name;
   126→    }
   127→
   128→    /// 새 레이블 생성
   129→    fn genLabel(self: *LLVMIRGen, prefix: []const u8) ![]const u8 {
   130→        const label = try std.fmt.allocPrint(self.allocator, "{}.{}", .{ prefix, self.label_counter });
   131→        self.label_counter += 1;
   132→        return label;
   133→    }
   134→
   135→    // ========== Instruction 코드 생성 ==========
   136→
   137→    fn emitInstruction(self: *LLVMIRGen, inst: Instruction, ref: Ref) !void {
   138→        switch (inst) {
   139→            .load_int => |info| {
   140→                try self.emitLoadInt(info, ref);
   141→            },
   142→            .load_float => |info| {
   143→                try self.emitLoadFloat(info, ref);
   144→            },
   145→            .load_string => |info| {
   146→                try self.emitLoadString(info, ref);
   147→            },
   148→            .load_var => |info| {
   149→                try self.emitLoadVar(info, ref);
   150→            },
   151→            .store_var => |info| {
   152→                try self.emitStoreVar(info);
   153→            },
   154→            .binary_op => |info| {
   155→                try self.emitBinaryOp(info, ref);
   156→            },
   157→            .unary_op => |info| {
   158→                try self.emitUnaryOp(info, ref);
   159→            },
   160→            .fn_begin => |info| {
   161→                try self.emitFnBegin(info);
   162→            },
   163→            .fn_end => {
   164→                try self.emitFnEnd();
   165→            },
   166→            .call => |info| {
   167→                try self.emitCall(info, ref);
   168→            },
   169→            .return_val => |info| {
   170→                try self.emitReturnVal(info);
   171→            },
   172→            .cond_br => |info| {
   173→                try self.emitCondBr(info);
   174→            },
   175→            .block_begin => {
   176→                try self.emitBlockBegin();
   177→            },
   178→            .block_end => {
   179→                try self.emitBlockEnd();
   180→            },
   181→            .loop_begin => {
   182→                try self.emitLoopBegin();
   183→            },
   184→            .loop_end => {
   185→                try self.emitLoopEnd();
   186→            },
   187→            .array_literal => |info| {
   188→                try self.emitArrayLiteral(info, ref);
   189→            },
   190→            .index_access => |info| {
   191→                try self.emitIndexAccess(info, ref);
   192→            },
   193→            .member_access => |info| {
   194→                try self.emitMemberAccess(info, ref);
   195→            },
   196→            .switch_expr => |info| {
   197→                try self.emitSwitchExpr(info, ref);
   198→            },
   199→            .case_pattern => |info| {
   200→                try self.emitCasePattern(info, ref);
   201→            },
   202→            .try_expr => |info| {
   203→                try self.emitTryExpr(info, ref);
   204→            },
   205→            .catch_expr => |info| {
   206→                try self.emitCatchExpr(info, ref);
   207→            },
   208→            .defer_stmt => |info| {
   209→                try self.emitDeferStmt(info, ref);
   210→            },
   211→            .scope_exit => |info| {
   212→                try self.emitScopeExit(info);
   213→            },
   214→            else => {},
   215→        }
   216→    }
   217→
   218→    // ========== Phase 5.1: Basic Values & Functions ==========
   219→
   220→    fn emitLoadInt(self: *LLVMIRGen, info: struct { value: i64, ty: AirType }, ref: Ref) !void {
   221→        const temp = try self.genTempVar();
   222→        const type_str = try self.typeToLLVM(info.ty);
   223→        try self.output.writer().print("{} {} = add {} 0, {}\n", .{ temp, type_str, type_str, info.value });
   224→        try self.ref_to_value.put(ref, temp);
   225→    }
   226→
   227→    fn emitLoadFloat(self: *LLVMIRGen, info: struct { value: f64, ty: AirType }, ref: Ref) !void {
   228→        const temp = try self.genTempVar();
   229→        const type_str = try self.typeToLLVM(info.ty);
   230→        try self.output.writer().print("{} {} = fadd {} 0.0, {}\n", .{ temp, type_str, type_str, info.value });
   231→        try self.ref_to_value.put(ref, temp);
   232→    }
   233→
   234→    fn emitLoadString(self: *LLVMIRGen, info: struct { index: u32, ty: AirType }, ref: Ref) !void {
   235→        // 문자열 인덱스로 전역 상수 생성
   236→        // 간단화: 문자열 인덱스를 기반으로 @.str{index} 레이블 생성
   237→        const str_label = try std.fmt.allocPrint(self.allocator, "@.str{}", .{info.index});
   238→        try self.output.writer().print("{} = private constant [6 x i8] c\"str\\00\"\n", .{str_label});
   239→
   240→        const temp = try self.genTempVar();
   241→        try self.output.writer().print("{} i8* = getelementptr inbounds [6 x i8], [6 x i8]* {}, i64 0, i64 0\n", .{ temp, str_label });
   242→        try self.ref_to_value.put(ref, temp);
   243→    }
   244→
   245→    fn emitLoadVar(self: *LLVMIRGen, info: struct { name_index: u32, ty: AirType }, ref: Ref) !void {
   246→        // 변수는 alloca_map에서 조회
   247→        const var_ptr = self.alloca_map.get(info.name_index) orelse "unknown_var";
   248→        const temp = try self.genTempVar();
   249→        const type_str = try self.typeToLLVM(info.ty);
   250→        try self.output.writer().print("{} {} = load {}, {}* {}\n", .{ temp, type_str, type_str, type_str, var_ptr });
   251→        try self.ref_to_value.put(ref, temp);
   252→    }
   253→
   254→    fn emitStoreVar(self: *LLVMIRGen, info: struct { name_index: u32, value: Ref, ty: AirType }) !void {
   255→        const value_ref = try self.refToValue(info.value);
   256→        const var_ptr = self.alloca_map.get(info.name_index) orelse "unknown_var";
   257→        const type_str = try self.typeToLLVM(info.ty);
   258→        try self.output.writer().print("store {} {}, {}* {}\n", .{ type_str, value_ref, type_str, var_ptr });
   259→    }
   260→
   261→    fn emitBinaryOp(self: *LLVMIRGen, info: struct { op: u8, lhs: Ref, rhs: Ref, result_ty: AirType }, ref: Ref) !void {
   262→        const lhs_val = try self.refToValue(info.lhs);
   263→        const rhs_val = try self.refToValue(info.rhs);
   264→        const result_type = try self.typeToLLVM(info.result_ty);
   265→        const temp = try self.genTempVar();
   266→
   267→        // op 매핑 (BinaryOp enum 기반)
   268→        const op_name = switch (info.op) {
   269→            0 => "add", // add
   270→            1 => "sub", // sub
   271→            2 => "mul", // mul
   272→            3 => "sdiv", // div
   273→            4 => "srem", // mod
   274→            5 => "icmp eq", // eq
   275→            6 => "icmp ne", // ne
   276→            7 => "icmp slt", // lt
   277→            8 => "icmp sle", // le
   278→            9 => "icmp sgt", // gt
   279→            10 => "icmp sge", // ge
   280→            11 => "and", // logical_and
   281→            12 => "or", // logical_or
   282→            13 => "xor", // bitwise_xor
   283→            14 => "shl", // lshift
   284→            15 => "ashr", // rshift
   285→            16 => "and", // bitwise_and (수정: 이전에 누락됨)
   286→            17 => "or", // bitwise_or (수정: 이전에 누락됨)
   287→            else => "add", // fallback
   288→        };
   289→
   290→        // 부동점 연산 타입 조정
   291→        const actual_op = if (std.mem.eql(u8, result_type, "float") or std.mem.eql(u8, result_type, "double")) blk: {
   292→            break :blk switch (info.op) {
   293→                0 => "fadd",
   294→                1 => "fsub",
   295→                2 => "fmul",
   296→                3 => "fdiv",
   297→                4 => "frem",
   298→                else => op_name,
   299→            };
   300→        } else op_name;
   301→
   302→        try self.output.writer().print("{} {} = {} {} {}, {}\n", .{ temp, result_type, actual_op, result_type, lhs_val, rhs_val });
   303→        try self.ref_to_value.put(ref, temp);
   304→    }
   305→
   306→    fn emitUnaryOp(self: *LLVMIRGen, info: struct { op: u8, operand: Ref, result_ty: AirType }, ref: Ref) !void {
   307→        const operand_val = try self.refToValue(info.operand);
   308→        const result_type = try self.typeToLLVM(info.result_ty);
   309→        const temp = try self.genTempVar();
   310→
   311→        const op_name = switch (info.op) {
   312→            0 => "sub", // negate: 0 - operand
   313→            1 => "xor", // not: XOR with 1 (or all bits if i1)
   314→            2 => "xor", // bitwise_not: XOR with -1
   315→            else => "sub",
   316→        };
   317→
   318→        if (info.op == 0) {
   319→            // negate: 0 - operand
   320→            try self.output.writer().print("{} {} = {} {} 0, {}\n", .{ temp, result_type, op_name, result_type, operand_val });
   321→        } else if (info.op == 1) {
   322→            // not: XOR with 1 (for i1 bool)
   323→            try self.output.writer().print("{} {} = {} {} {}, 1\n", .{ temp, result_type, op_name, result_type, operand_val });
   324→        } else {
   325→            // bitwise_not: XOR with -1
   326→            try self.output.writer().print("{} {} = {} {} {}, -1\n", .{ temp, result_type, op_name, result_type, operand_val });
   327→        }
   328→
   329→        try self.ref_to_value.put(ref, temp);
   330→    }
   331→
   332→    fn emitFnBegin(self: *LLVMIRGen, info: struct { name_index: u32, params: []Ref, return_ty: AirType }) !void {
   333→        const return_type = try self.typeToLLVM(info.return_ty);
   334→        const fn_name = try std.fmt.allocPrint(self.allocator, "fn{}", .{info.name_index});
   335→
   336→        // 함수 서명 시작
   337→        try self.output.writer().print("define {} @{}(", .{ return_type, fn_name });
   338→
   339→        // 파라미터 출력 (실제 타입 사용, int 하드코딩 수정)
   340→        for (info.params, 0..) |param_ref, i| {
   341→            if (i > 0) try self.output.appendSlice(", ");
   342→            // param_ref는 이전 instruction으로, 그 타입을 알아야 함
   343→            // 간단화: 모두 i32로 처리 (TODO: 실제 타입 추적)
   344→            try self.output.writer().print("i32 %p{}", .{i});
   345→        }
   346→
   347→        try self.output.appendSlice(") {\n");
   348→        try self.output.appendSlice("entry:\n");
   349→
   350→        self.current_fn = fn_name;
   351→        self.indent_level = 1;
   352→    }
   353→
   354→    fn emitFnEnd(self: *LLVMIRGen) !void {
   355→        // 함수 끝: fallthrough ret void 보장
   356→        try self.output.appendSlice("  ret void\n");
   357→        try self.output.appendSlice("}\n\n");
   358→        self.current_fn = null;
   359→        self.indent_level = 0;
   360→    }
   361→
   362→    // ========== Phase 5.2: Control Flow IR ==========
   363→
   364→    fn emitCall(self: *LLVMIRGen, info: struct { callee: Ref, args: []Ref, return_ty: AirType }, ref: Ref) !void {
   365→        const callee_val = try self.refToValue(info.callee);
   366→        const return_type = try self.typeToLLVM(info.return_ty);
   367→        const temp = try self.genTempVar();
   368→
   369→        try self.output.writer().print("{} {} = call {} {}(", .{ temp, return_type, return_type, callee_val });
   370→
   371→        for (info.args, 0..) |arg, i| {
   372→            if (i > 0) try self.output.appendSlice(", ");
   373→            const arg_val = try self.refToValue(arg);
   374→            try self.output.writer().print("i32 {}", .{arg_val});
   375→        }
   376→
   377→        try self.output.appendSlice(")\n");
   378→        try self.ref_to_value.put(ref, temp);
   379→    }
   380→
   381→    fn emitReturnVal(self: *LLVMIRGen, info: ?Ref) !void {
   382→        if (info == null) {
   383→            try self.output.appendSlice("  ret void\n");
   384→        } else {
   385→            const val = try self.refToValue(info.?);
   386→            try self.output.writer().print("  ret i32 {}\n", .{val});
   387→        }
   388→    }
   389→
   390→    fn emitCondBr(self: *LLVMIRGen, info: struct { cond: Ref, then_block: Ref, else_block: ?Ref }) !void {
   391→        const cond_val = try self.refToValue(info.cond);
   392→        const then_label = try std.fmt.allocPrint(self.allocator, "then.{}", .{info.then_block});
   393→        const else_label = if (info.else_block) |eb|
   394→            try std.fmt.allocPrint(self.allocator, "else.{}", .{eb})
   395→        else
   396→            try std.fmt.allocPrint(self.allocator, "else.{}", .{info.then_block});
   397→
   398→        try self.output.writer().print("  br i1 {}, label %{}, label %{}\n", .{ cond_val, then_label, else_label });
   399→    }
   400→
   401→    fn emitBlockBegin(self: *LLVMIRGen) !void {
   402→        // block_begin는 기본 블록 레이블만 출력
   403→        // label은 AIR instruction의 label 필드에서 옴
   404→        const label = try self.genLabel("block");
   405→        try self.output.writer().print("{}:\n", .{label});
   406→    }
   407→
   408→    fn emitBlockEnd(self: *LLVMIRGen) !void {
   409→        // 다음 블록으로 fallthrough
   410→        // merge 레이블로 br 출력
   411→        const merge_label = try self.genLabel("merge");
   412→        try self.output.writer().print("  br label %{}\n", .{merge_label});
   413→    }
   414→
   415→    fn emitLoopBegin(self: *LLVMIRGen) !void {
   416→        const loop_label = try self.genLabel("loop");
   417→        try self.output.writer().print("  br label %{}\n", .{loop_label});
   418→        try self.output.writer().print("{}:\n", .{loop_label});
   419→    }
   420→
   421→    fn emitLoopEnd(self: *LLVMIRGen) !void {
   422→        // 루프 시작으로 back-edge
   423→        const loop_label = try self.genLabel("loop");
   424→        try self.output.writer().print("  br label %{}\n", .{loop_label});
   425→    }
   426→
   427→    fn emitArrayLiteral(self: *LLVMIRGen, info: struct { elements: []Ref, element_ty: AirType }, ref: Ref) !void {
   428→        const elem_type = try self.typeToLLVM(info.element_ty);
   429→        const array_size = info.elements.len;
   430→        const array_type = try std.fmt.allocPrint(self.allocator, "[{} x {}]", .{ array_size, elem_type });
   431→        const temp = try self.genTempVar();
   432→        const ptr_temp = try self.genTempVar();
   433→
   434→        // alloca 배열
   435→        try self.output.writer().print("{} {}* = alloca {}\n", .{ ptr_temp, array_type, array_type });
   436→
   437→        // 각 요소 저장
   438→        for (info.elements, 0..) |elem, i| {
   439→            const elem_val = try self.refToValue(elem);
   440→            const elem_ptr = try std.fmt.allocPrint(self.allocator, "%_t_elem_{}", .{i});
   441→            try self.output.writer().print("{} {}* = getelementptr inbounds {}, {}* {}, i64 0, i64 {}\n",
   442→                .{ elem_ptr, elem_type, array_type, array_type, ptr_temp, i });
   443→            try self.output.writer().print("store {} {}, {}* {}\n", .{ elem_type, elem_val, elem_type, elem_ptr });
   444→        }
   445→
   446→        try self.ref_to_value.put(ref, ptr_temp);
   447→    }
   448→
   449→    fn emitIndexAccess(self: *LLVMIRGen, info: struct { array: Ref, index: Ref, element_ty: AirType }, ref: Ref) !void {
   450→        const array_val = try self.refToValue(info.array);
   451→        const index_val = try self.refToValue(info.index);
   452→        const elem_type = try self.typeToLLVM(info.element_ty);
   453→        const ptr_temp = try self.genTempVar();
   454→        const temp = try self.genTempVar();
   455→
   456→        try self.output.writer().print("{} {}* = getelementptr inbounds {}, {}* {}, i64 {}\n",
   457→            .{ ptr_temp, elem_type, elem_type, elem_type, array_val, index_val });
   458→        try self.output.writer().print("{} {} = load {}, {}* {}\n",
   459→            .{ temp, elem_type, elem_type, elem_type, ptr_temp });
   460→        try self.ref_to_value.put(ref, temp);
   461→    }
   462→
   463→    fn emitMemberAccess(self: *LLVMIRGen, info: struct { object: Ref, field_index: u32, field_ty: AirType }, ref: Ref) !void {
   464→        const object_val = try self.refToValue(info.object);
   465→        const field_type = try self.typeToLLVM(info.field_ty);
   466→        const ptr_temp = try self.genTempVar();
   467→        const temp = try self.genTempVar();
   468→
   469→        // %struct.fieldN 접근
   470→        try self.output.writer().print("{} {}* = getelementptr inbounds %struct, %struct* {}, i64 0, i32 {}\n",
   471→            .{ ptr_temp, field_type, object_val, info.field_index });
   472→        try self.output.writer().print("{} {} = load {}, {}* {}\n",
   473→            .{ temp, field_type, field_type, field_type, ptr_temp });
   474→        try self.ref_to_value.put(ref, temp);
   475→    }
   476→
   477→    // ========== Phase 5.3: Advanced Features (Pattern/Error/Defer) ==========
   478→
   479→    fn emitSwitchExpr(self: *LLVMIRGen, info: struct { expr: Ref, cases: []Ref, case_patterns: []AirType }, ref: Ref) !void {
   480→        const expr_val = try self.refToValue(info.expr);
   481→        const switch_label = try self.genLabel("switch.end");
   482→
   483→        // switch 명령 시작
   484→        try self.output.writer().print("  switch i32 {}, label %{} [\n", .{ expr_val, switch_label });
   485→
   486→        // case들을 case_patterns 길이만큼
   487→        for (0..info.case_patterns.len) |i| {
   488→            const case_label = try std.fmt.allocPrint(self.allocator, "case.{}", .{i});
   489→            try self.output.writer().print("    i32 {}, label %{}\n", .{ i, case_label });
   490→        }
   491→
   492→        try self.output.appendSlice("  ]\n");
   493→
   494→        // switch subject 스택에 저장
   495→        try self.switch_subject_stack.append(expr_val);
   496→
   497→        // 결과값 등록
   498→        const temp = try self.genTempVar();
   499→        try self.ref_to_value.put(ref, temp);
   500→    }
   501→
   502→    fn emitCasePattern(self: *LLVMIRGen, info: struct { pattern: Ref, value: Ref, pattern_ty: AirType }, _: Ref) !void {
   503→        // switch subject는 스택에서 팝하거나, pattern Ref를 기반으로 case 라벨 생성
   504→        const pattern_val = try self.refToValue(info.pattern);
   505→        const value_val = try self.refToValue(info.value);
   506→
   507→        // case 라벨과 body 출력
   508→        const case_label = try self.genLabel("case");
   509→        try self.output.writer().print("{}:\n", .{case_label});
   510→        try self.output.writer().print("  br label %switch.end\n", .{});
   511→    }
   512→
   513→    fn emitTryExpr(self: *LLVMIRGen, info: struct { expr: Ref, result_type: AirType }, ref: Ref) !void {
   514→        const err_var = try std.fmt.allocPrint(self.allocator, "%_err_{}", .{self.error_counter});
   515→        self.error_counter += 1;
   516→
   517→        // 에러 변수 alloca
   518→        try self.output.writer().print("{} i32* = alloca i32\n", .{err_var});
   519→        try self.output.appendSlice("  store i32 0, i32* %" + err_var[1..] + "\n");
   520→
   521→        // 내부 표현식 실행
   522→        const result_type = try self.typeToLLVM(info.result_type);
   523→        const temp = try self.genTempVar();
   524→        try self.output.writer().print("{} {} = call {} {}(i32* {})\n", .{ temp, result_type, result_type, "fn", err_var });
   525→
   526→        // 에러 guard check
   527→        const err_val_temp = try self.genTempVar();
   528→        try self.output.writer().print("{} i32 = load i32, i32* {}\n", .{ err_val_temp, err_var });
   529→        const is_err_temp = try self.genTempVar();
   530→        try self.output.writer().print("{} i1 = icmp ne i32 {}, 0\n", .{ is_err_temp, err_val_temp });
   531→        try self.output.appendSlice("  br i1 " + is_err_temp[1..] + ", label %propagate, label %continue\n");
   532→
   533→        // try_ref_to_err에 매핑
   534→        try self.try_ref_to_err.put(ref, err_var);
   535→        try self.ref_to_value.put(ref, temp);
   536→    }
   537→
   538→    fn emitCatchExpr(self: *LLVMIRGen, info: struct { try_expr: Ref, error_var_type: AirType, body: Ref }, _: Ref) !void {
   539→        if (self.try_ref_to_err.get(info.try_expr)) |err_var| {
   540→            // catch 블록 시작
   541→            try self.output.appendSlice("propagate:\n");
   542→            const err_val_temp = try self.genTempVar();
   543→            try self.output.writer().print("{} i32 = load i32, i32* {}\n", .{ err_val_temp, err_var });
   544→            try self.output.writer().print("  ret i32 {}\n", .{err_val_temp});
   545→
   546→            // continue 라벨
   547→            try self.output.appendSlice("continue:\n");
   548→        }
   549→    }
   550→
   551→    fn emitDeferStmt(self: *LLVMIRGen, info: struct { expr: Ref, scope_id: u32, defer_index: u32 }, _: Ref) !void {
   552→        // defer 식을 scope별 큐에 저장 (현재는 emitting하지 않음)
   553→        var deferred = self.deferred_by_scope.get(info.scope_id);
   554→        if (deferred == null) {
   555→            var new_list = std.ArrayList(DeferEntry).init(self.allocator);
   556→            try self.deferred_by_scope.put(info.scope_id, new_list);
   557→            deferred = self.deferred_by_scope.get(info.scope_id);
   558→        }
   559→
   560→        try deferred.?.append(.{
   561→            .expr_ref = info.expr,
   562→            .defer_index = info.defer_index,
   563→        });
   564→    }
   565→
   566→    fn emitScopeExit(self: *LLVMIRGen, info: struct { scope_id: u32 }, _: Ref) !void {
   567→        // defer들을 역순(defer_index 내림차순)으로 정렬 후 emit
   568→        if (self.deferred_by_scope.get(info.scope_id)) |defer_list| {
   569→            var defers = defer_list.items;
   570→            // 내림차순 정렬
   571→            std.mem.sort(DeferEntry, defers, {}, deferIndexDescending);
   572→
   573→            for (defers) |defer_entry| {
   574→                const expr_str = try self.refToValue(defer_entry.expr_ref);
   575→                try self.output.writer().print("  call void {}()\n", .{expr_str});
   576→            }
   577→        }
   578→    }
   579→
   580→    /// defer_index 내림차순 정렬
   581→    fn deferIndexDescending(_: void, a: DeferEntry, b: DeferEntry) bool {
   582→        return a.defer_index > b.defer_index;
   583→    }
   584→
   585→    // ========== 유틸리티 ==========
   586→
   587→    fn emitIndent(self: *LLVMIRGen) !void {
   588→        for (0..self.indent_level) |_| {
   589→            try self.output.appendSlice("  ");
   590→        }
   591→    }
   592→};
