   203→/// Type 유틸리티 함수들
   204→pub fn typeEq(t1: Type, t2: Type) bool {
   205→    switch (t1) {
   206→        .void => return t2 == .void,
   207→        .i32 => return t2 == .i32,
   208→        .i64 => return t2 == .i64,
   209→        .f32 => return t2 == .f32,
   210→        .f64 => return t2 == .f64,
   211→        .bool => return t2 == .bool,
   212→        .string => return t2 == .string,
   213→        .unknown => return t2 == .unknown,
   214→        .array => |arr1| {
   215→            if (t2 == .array) {
   216→                const arr2 = t2.array;
   217→                return typeEq(arr1.element_ty.*, arr2.element_ty.*) and
   218→                    arr1.len == arr2.len;
   219→            }
   220→            return false;
   221→        },
   222→        .function => {
   223→            // 함수 타입 비교는 복잡하므로 나중에 구현
   224→            return false;
   225→        },
   226→    }
   227→}
   228→
   229→pub fn typeName(t: Type) []const u8 {
   230→    return switch (t) {
   231→        .void => "void",
   232→        .i32 => "i32",
   233→        .i64 => "i64",
   234→        .f32 => "f32",
   235→        .f64 => "f64",
   236→        .bool => "bool",
   237→        .string => "string",
   238→        .unknown => "unknown",
   239→        .array => "array",
   240→        .function => "function",
   241→    };
   242→}
