   244→/// AIR 디버깅용 출력 함수
   245→pub fn printAir(air: *const Air, indent: usize) void {
   246→    const spaces = " " ** indent;
   247→    const stdout = std.io.getStdOut().writer();
   248→
   249→    stdout.print("{s}=== AIR Instructions ===\n", .{spaces}) catch {};
   250→
   251→    for (air.instructions.items, 0..) |inst, idx| {
   252→        stdout.print("{s}[{}] ", .{ spaces, idx }) catch {};
   253→
   254→        switch (inst) {
   255→            .load_int => |data| {
   256→                stdout.print("load_int {} ({s})\n", .{ data.value, typeName(data.ty) }) catch {};
   257→            },
   258→            .load_float => |data| {
   259→                stdout.print("load_float {} ({s})\n", .{ data.value, typeName(data.ty) }) catch {};
   260→            },
   261→            .load_string => |data| {
   262→                stdout.print("load_string @{} ({s})\n", .{ data.index, typeName(data.ty) }) catch {};
   263→            },
   264→            .load_var => |data| {
   265→                stdout.print("load_var @{} ({s})\n", .{ data.name_index, typeName(data.ty) }) catch {};
   266→            },
   267→            .store_var => |data| {
   268→                stdout.print("store_var @{} = %{} ({s})\n", .{ data.name_index, data.value, typeName(data.ty) }) catch {};
   269→            },
   270→            .binary_op => |data| {
   271→                stdout.print("binary_op {:s} %{} %{} → {s}\n", .{ @tagName(data.op), data.lhs, data.rhs, typeName(data.result_ty) }) catch {};
   272→            },
   273→            .unary_op => |data| {
   274→                stdout.print("unary_op {:s} %{} → {s}\n", .{ @tagName(data.op), data.operand, typeName(data.result_ty) }) catch {};
   275→            },
   276→            .fn_begin => |data| {
   277→                stdout.print("fn_begin @{} (params: {}, return: {s})\n", .{ data.name_index, data.params.len, typeName(data.return_ty) }) catch {};
   278→            },
   279→            .fn_end => {
   280→                stdout.print("fn_end\n", .{}) catch {};
   281→            },
   282→            .call => |data| {
   283→                stdout.print("call %{} (args: {}, return: {s})\n", .{ data.callee, data.args.len, typeName(data.return_ty) }) catch {};
   284→            },
   285→            .return_val => |ret| {
   286→                if (ret) |r| {
   287→                    stdout.print("return %{}\n", .{r}) catch {};
   288→                } else {
   289→                    stdout.print("return void\n", .{}) catch {};
   290→                }
   291→            },
   292→            .block_begin => |data| {
   293→                stdout.print("block_begin @{}\n", .{data.label}) catch {};
   294→            },
   295→            .block_end => {
   296→                stdout.print("block_end\n", .{}) catch {};
   297→            },
   298→            .array_literal => |data| {
   299→                stdout.print("array_literal (elements: {}, type: {s})\n", .{ data.elements.len, typeName(data.element_ty) }) catch {};
   300→            },
   301→            .noop => {
   302→                stdout.print("noop\n", .{}) catch {};
   303→            },
   304→            else => {
   305→                stdout.print("{s}\n", .{@tagName(inst)}) catch {};
   306→            },
   307→        }
   308→    }
   309→
   310→    stdout.print("{s}=== Strings ===\n", .{spaces}) catch {};
   311→    var iter = air.strings.iterator();
   312→    var idx: u32 = 0;
   313→    while (iter.next()) |entry| {
   314→        stdout.print("{s}@{}: \"{s}\"\n", .{ spaces, idx, entry.value_ptr.* }) catch {};
   315→        idx += 1;
   316→    }
   317→}
